from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'put':
            key, value = op[2], op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                    if len(cache) >= capacity:
                        # evict LRU, but need to consider expired ones don't count
                        # find first non-expired to evict? Actually eviction just removes LRU entry regardless
                        # but expired entries shouldn't count as occupying space? Let's clean expired first
                        # Clean all expired entries
                        expired_keys = [k for k, (v, wt) in cache.items() if t >= wt + ttl]
                        for k in expired_keys:
                            del cache[k]
                        if len(cache) >= capacity:
                            oldest_key = next(iter(cache))
                            del cache[oldest_key]
                    cache[key] = (value, t)
                    cache.move_to_end(key)
                else:
                    # update existing, move to end
                    cache[key] = (value, t)
                    cache.move_to_end(key)
            else:
                # clean expired entries first to make room accounting accurate
                expired_keys = [k for k, (v, wt) in cache.items() if t >= wt + ttl]
                for k in expired_keys:
                    del cache[k]
                if len(cache) >= capacity:
                    oldest_key = next(iter(cache))
                    del cache[oldest_key]
                cache[key] = (value, t)
                cache.move_to_end(key)
        elif kind == 'get':
            key = op[2]
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)
    return results

